-- Sonda publica de cobertura documental de columnas para un conjunto de tablas
-- declarado por el repositorio (las tablas que el cliente consume). Solo metadatos.
create or replace function public.vexforge_column_doc_coverage(_tables text[])
returns table(total_columns integer, undocumented integer, missing text[])
language sql
stable
security definer
set search_path = public, pg_catalog
as $$
  with c as (
    select cl.relname || '.' || a.attname as ref,
           col_description(a.attrelid, a.attnum) as cmt
    from pg_attribute a
    join pg_class cl on cl.oid = a.attrelid
    join pg_namespace n on n.oid = cl.relnamespace
    where n.nspname = 'public'
      and cl.relkind = 'r'
      and a.attnum > 0
      and not a.attisdropped
      and cl.relname = any(_tables)
  )
  select
    count(*)::integer,
    count(*) filter (where cmt is null)::integer,
    coalesce(array_agg(ref order by ref) filter (where cmt is null), '{}'::text[])
  from c;
$$;

comment on function public.vexforge_column_doc_coverage(text[]) is
  'VE-DOC-4: cobertura documental de columnas para las tablas indicadas (total, sin comentario y referencias faltantes). Solo metadatos, sin datos de jugador.';

revoke all on function public.vexforge_column_doc_coverage(text[]) from public;
grant execute on function public.vexforge_column_doc_coverage(text[]) to anon, authenticated, service_role;
